function summarizeProjectActivity(
  worktrees: Worktree[],
  activityByWorktreePath: Record<string, ActivitySummary | undefined> | undefined,
  unreadWorktreePaths: Record<string, boolean> | undefined,
): ActivitySummary {
  const summaries = worktrees
    .map((worktree) => activityByWorktreePath?.[worktree.path])
    .filter((summary): summary is ActivitySummary => Boolean(summary));
  const hasUnread = worktrees.some((worktree) => Boolean(unreadWorktreePaths?.[worktree.path]));
  return combineActivitySummaries(summaries, hasUnread);
}

/**
 * Worktrees carry their owning project inside their `orca/<wsId>/<slug>` branch name. Anything
 * without a matching registered project belongs to the active project, which is the only project
 * whose worktrees the workspace store actually holds.
 */
function groupWorktreesByProject(
  worktrees: Worktree[],
  projects: RegisteredProject[],
  activeProjectId: string | undefined,
) {
  const grouped = new Map<string, Worktree[]>();
  for (const project of projects) grouped.set(project.workspaceId, []);

  for (const worktree of worktrees) {
    const ownerId = worktreeIdentity(worktree)?.wsId;
    const owner = ownerId && grouped.has(ownerId) ? ownerId : activeProjectId;
    if (!owner) continue;
    const bucket = grouped.get(owner);
    if (bucket) bucket.push(worktree);
  }

  return grouped;
}

function seedCollapsedProjects(
  collapsed: Set<string>,
  projects: RegisteredProject[],
  activeProjectId: string | undefined,
) {
  const seeded = projects.filter(
    (project) => project.workspaceId !== activeProjectId && !collapsed.has(project.workspaceId),
  );
  if (seeded.length === 0) return collapsed;
  const next = new Set(collapsed);
  for (const project of seeded) next.add(project.workspaceId);
  return next;
}

/** Returns `null` when the accordion has never been persisted, so callers can apply defaults. */
function loadCollapsedProjects(): Set<string> | null {
  try {
    const raw = getMigratedItem(SIDEBAR_COLLAPSED_PROJECTS_STORAGE_KEY);
    if (!raw) return null;
    const parsed: unknown = JSON.parse(raw);
    if (!Array.isArray(parsed)) return null;
    return new Set(parsed.filter((id): id is string => typeof id === "string"));
  } catch {
    return null;
  }
}

function persistCollapsedProjects(collapsed: Set<string>) {
  try {
    window.localStorage.setItem(SIDEBAR_COLLAPSED_PROJECTS_STORAGE_KEY, JSON.stringify([...collapsed]));
  } catch {
    // A storage failure should not break accordion toggling for this session.
  }
}

function loadSidebarWidth() {
  try {
    const raw = getMigratedItem(SIDEBAR_WIDTH_STORAGE_KEY);
    const stored = Number(raw);
    return Number.isFinite(stored) && stored > 0 ? clampSidebarWidth(stored) : DEFAULT_SIDEBAR_WIDTH;
  } catch {
    return DEFAULT_SIDEBAR_WIDTH;
  }
}

function persistSidebarWidth(width: number) {
  try {
    window.localStorage.setItem(SIDEBAR_WIDTH_STORAGE_KEY, String(clampSidebarWidth(width)));
  } catch {
    // A storage failure should not break pointer resizing for this session.
  }
}

function clampSidebarWidth(width: number) {
  return Math.min(MAX_SIDEBAR_WIDTH, Math.max(MIN_SIDEBAR_WIDTH, Math.round(width)));
}

import { GitBranch, Search, TerminalSquare, X } from "lucide-react";
import { useEffect, useMemo, useRef, useState } from "react";

import { SHORTCUTS, isMacShortcutPlatform, shortcutLabel } from "../lib/shortcuts";
import type { WorkspaceTab, Worktree } from "../lib/types";

export type CommandPaletteProps = {
  open: boolean;
  worktrees: Worktree[];
  tabs: WorkspaceTab[];
  onSelectWorktree: (worktree: Worktree) => void;
  onSelectTab: (tabId: string) => void;
  onClose: () => void;
};

export function CommandPalette({ open, worktrees, tabs, onSelectWorktree, onSelectTab, onClose }: CommandPaletteProps) {
  const [query, setQuery] = useState("");
  const inputRef = useRef<HTMLInputElement>(null);
  const isMac = isMacShortcutPlatform();
  const normalizedQuery = query.trim().toLowerCase();
  const filteredWorktrees = useMemo(
    () => worktrees.filter((worktree) => worktreeSearchText(worktree).includes(normalizedQuery)),
    [normalizedQuery, worktrees],
  );
  const filteredTabs = useMemo(
    () => tabs.filter((tab) => tab.label.toLowerCase().includes(normalizedQuery)),
    [normalizedQuery, tabs],
  );

  useEffect(() => {
    if (!open) {
      setQuery("");
      return;
    }
    inputRef.current?.focus();
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key !== "Escape") return;
      event.preventDefault();
      onClose();
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [onClose, open]);

  if (!open) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-start justify-center bg-black/60 px-4 pt-[12vh] backdrop-blur-sm" onMouseDown={onClose}>
      <div
        role="dialog"
        aria-label="Command palette"
        aria-modal="true"
        className="w-full max-w-2xl animate-enter overflow-hidden rounded-xl border border-border bg-popover shadow-2xl"
        onMouseDown={(event) => event.stopPropagation()}
      >
        <div className="flex items-center gap-2 border-b border-border px-3">
          <Search className="size-4 shrink-0 text-muted-foreground" />
          <input
            ref={inputRef}
            value={query}
            onChange={(event) => setQuery(event.target.value)}
            placeholder="Search worktrees and terminal tabs"
            className="h-11 min-w-0 flex-1 bg-transparent text-sm text-foreground outline-none placeholder:text-muted-foreground"
          />
          <button type="button" onClick={onClose} aria-label="Close command palette" className="rounded-md p-1 text-muted-foreground hover:bg-accent hover:text-foreground">
            <X className="size-4" />
          </button>
        </div>

        <div className="max-h-[55vh] overflow-y-auto p-2 scrollbar-sleek">
          {filteredWorktrees.length > 0 ? (
            <section aria-label="Worktrees" className="mb-2">
              <h2 className="px-2 py-1 text-[10px] font-semibold uppercase tracking-wider text-muted-foreground">Worktrees</h2>
              {filteredWorktrees.map((worktree) => (
                <button
                  key={worktree.path}
                  type="button"
                  onClick={() => {
                    onSelectWorktree(worktree);
                    onClose();
                  }}
                  className="flex w-full items-center gap-2 rounded-md px-2 py-2 text-left text-sm hover:bg-accent"
                >
                  <GitBranch className="size-4 shrink-0 text-muted-foreground" />
                  <span className="min-w-0 flex-1">
                    <span className="block truncate text-foreground">{worktreeName(worktree)}</span>
                    <span className="block truncate font-mono text-[10px] text-muted-foreground">{branchName(worktree)}</span>
                  </span>
                </button>
              ))}
            </section>
          ) : null}

          {filteredTabs.length > 0 ? (
            <section aria-label="Terminal tabs">
              <h2 className="px-2 py-1 text-[10px] font-semibold uppercase tracking-wider text-muted-foreground">Terminal tabs</h2>
              {filteredTabs.map((tab) => (
                <button
                  key={tab.id}
                  type="button"
                  onClick={() => {
                    onSelectTab(tab.id);
                    onClose();
                  }}
                  className="flex w-full items-center gap-2 rounded-md px-2 py-2 text-left text-sm text-foreground hover:bg-accent"
                >
                  <TerminalSquare className="size-4 shrink-0 text-muted-foreground" />
                  <span className="min-w-0 flex-1 truncate">{tab.label}</span>
                </button>
              ))}
            </section>
          ) : null}

          {filteredWorktrees.length === 0 && filteredTabs.length === 0 ? (
            <div className="px-3 py-8 text-center text-xs text-muted-foreground">No matching worktrees or terminal tabs.</div>
          ) : null}
        </div>

        <div className="flex flex-wrap gap-x-3 gap-y-1 border-t border-border px-3 py-2 text-[10px] text-muted-foreground">
          {SHORTCUTS.map((shortcut) => (
            <span key={shortcut.id} className="inline-flex items-center gap-1">
              <span>{shortcut.title}</span>
              <kbd className="rounded border border-border bg-muted px-1 py-px text-foreground">{shortcutLabel(shortcut.id, isMac)}</kbd>
            </span>
          ))}
        </div>
      </div>
    </div>
  );
}

function branchName(worktree: Worktree) {
  return worktree.branch?.replace(/^refs\/heads\//, "") ?? "detached HEAD";
}

function worktreeName(worktree: Worktree) {
  if (worktree.path === ".") return "main";
  return worktree.path.split(/[\\/]/).filter(Boolean).at(-1) ?? worktree.path;
}

function worktreeSearchText(worktree: Worktree) {
  return `${worktreeName(worktree)} ${branchName(worktree)} ${worktree.path}`.toLowerCase();
}

import { open } from "@tauri-apps/plugin-dialog";
import { FolderGit2, FolderPlus, GitBranch, LoaderCircle, X } from "lucide-react";
import { FormEvent, useEffect, useRef, useState } from "react";

import {
  createWorktree,
  isTauriRuntime,
  listProjectBranches,
  registerProject,
  type LocalBranch,
  type RegisteredProject,
} from "../lib/tauri";
import type { Worktree } from "../lib/types";

const fieldClass =
  "h-8 w-full rounded-md border border-input bg-background px-2 text-xs text-foreground outline-none transition-colors placeholder:text-muted-foreground/45 focus:border-ring";

function checkIsTauri(): boolean {
  try {
    return Boolean(isTauriRuntime());
  } catch {
    return false;
  }
}

export function deriveWorkspaceId(folderPath: string, existingProjects: RegisteredProject[] = []): string {
  const normalized = folderPath.replace(/[/\\]+$/, "");
  const basename = normalized.split(/[/\\]/).pop() || "";
  let baseId = basename.replace(/[\s/\\\x00-\x1f\x7f]+/g, "-").replace(/^-+/, "");
  if (!baseId) {
    baseId = "project";
  }
  const existingIds = new Set(existingProjects.map((p) => p.workspaceId));
  if (!existingIds.has(baseId)) {
    return baseId;
  }
  let index = 2;
  while (existingIds.has(`${baseId}-${index}`)) {
    index++;
  }
  return `${baseId}-${index}`;
}

type AddProjectDialogProps = {
  projects?: RegisteredProject[];
  onClose: () => void;
  onRegistered: (project: RegisteredProject) => void;
};

export function AddProjectDialog({ projects = [], onClose, onRegistered }: AddProjectDialogProps) {
  const [workspaceId, setWorkspaceId] = useState("");
  const [repoPath, setRepoPath] = useState("");
  const [selectedPath, setSelectedPath] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const onCloseRef = useRef(onClose);
  onCloseRef.current = onClose;
  const onRegisteredRef = useRef(onRegistered);
  onRegisteredRef.current = onRegistered;
  const projectsRef = useRef(projects);
  projectsRef.current = projects;

  const pickerOpenedRef = useRef(false);
  const isTauri = checkIsTauri();

  useEffect(() => {
    if (!isTauri || pickerOpenedRef.current) return;
    pickerOpenedRef.current = true;
    let alive = true;
    void open({
      directory: true,
      multiple: false,
      title: "Add Project",
    })
      .then((selected) => {
        if (!alive) return;
        if (typeof selected === "string" && selected.length > 0) {
          setSelectedPath(selected);
        } else {
          onCloseRef.current();
        }
      })
      .catch((cause) => {
        console.error(cause);
        if (!alive) return;
        const message = cause instanceof Error ? cause.message : String(cause);
        setError(message || "Could not open folder picker.");
      });
    return () => {
      alive = false;
    };
  }, [isTauri]);

  if (isTauri && selectedPath) {
    const handleConfirm = async () => {
      if (submitting || !selectedPath) return;
      setSubmitting(true);
      setError(null);
      const derivedId = deriveWorkspaceId(selectedPath, projectsRef.current);
      try {
        const project = await registerProject({ workspaceId: derivedId, repoPath: selectedPath });
        onRegisteredRef.current(project);
        onCloseRef.current();
      } catch (cause) {
        setError(cause instanceof Error ? cause.message : "Could not register this project.");
      } finally {
        setSubmitting(false);
      }
    };

    return (
      <div className="fixed inset-0 z-40 flex items-center justify-center bg-black/45 p-6" role="presentation">
        <div
          role="dialog"
          aria-label="Add Project"
          className="w-full max-w-[420px] overflow-hidden rounded-lg border border-border bg-card shadow-2xl"
        >
          <div className="flex h-9 items-center border-b border-border px-3">
            <FolderGit2 className="mr-2 size-3.5 text-muted-foreground" />
            <h2 className="text-[13px] font-medium">Add Project</h2>
            <button
              type="button"
              aria-label="Close Add Project"
              disabled={submitting}
              className="ml-auto rounded p-1 text-muted-foreground hover:bg-accent hover:text-foreground disabled:opacity-45"
              onClick={() => onCloseRef.current()}
            >
              <X className="size-3.5" />
            </button>
          </div>
          <div className="space-y-3 p-3">
            <p className="text-xs text-muted-foreground">
              Add this folder as a separate Ferryx project.
            </p>
            <div className="rounded-md border border-border/70 bg-muted/35 px-3 py-2 text-xs">
              <div className="break-all font-mono text-muted-foreground">{selectedPath}</div>
            </div>
            {error ? <p className="text-xs text-destructive">{error}</p> : null}
          </div>
          <div className="flex justify-end gap-2 border-t border-border px-3 py-2">
            <button
              type="button"
              disabled={submitting}
              className="h-7 rounded-md border border-border px-2.5 text-xs text-muted-foreground hover:bg-accent disabled:opacity-45"
              onClick={() => onCloseRef.current()}
            >
              Cancel
            </button>
            <button
              type="button"
              disabled={submitting || !selectedPath}
              onClick={handleConfirm}
              className="inline-flex h-7 items-center gap-1.5 rounded-md bg-primary px-3 text-xs font-medium text-primary-foreground disabled:opacity-45"
            >
              {submitting ? (
                <LoaderCircle className="size-3.5 animate-spin" />
              ) : (
                <FolderPlus className="size-3.5" />
              )}
              Add Project
            </button>
          </div>
        </div>
      </div>
    );
  }

  if (isTauri && !error) {
    return null;
  }

  const submit = async (event: FormEvent) => {
    event.preventDefault();
    const trimmedWorkspaceId = workspaceId.trim();
    const trimmedPath = repoPath.trim();
    if (!trimmedWorkspaceId || !trimmedPath || submitting) return;
    setSubmitting(true);
    setError(null);
    try {
      const project = await registerProject({ workspaceId: trimmedWorkspaceId, repoPath: trimmedPath });
      onRegisteredRef.current(project);
      onCloseRef.current();
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : "Could not register this project.");
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 z-40 flex items-center justify-center bg-black/45 p-6" role="presentation">
      <form
        aria-label="Add Project"
        className="w-full max-w-[420px] overflow-hidden rounded-lg border border-border bg-card shadow-2xl"
        onSubmit={submit}
      >
        <div className="flex h-9 items-center border-b border-border px-3">
          <FolderGit2 className="mr-2 size-3.5 text-muted-foreground" />
          <h2 className="text-[13px] font-medium">Add Project</h2>
          <button
            type="button"
            aria-label="Close Add Project"
            className="ml-auto rounded p-1 text-muted-foreground hover:bg-accent hover:text-foreground"
            onClick={() => onCloseRef.current()}
          >
            <X className="size-3.5" />
          </button>
        </div>
        <div className="space-y-3 p-3">
          <label className="block space-y-1 text-[11px] text-muted-foreground">
            <span>Workspace id</span>
            <input
              aria-label="Workspace id"
              className={fieldClass}
              value={workspaceId}
              onChange={(event) => setWorkspaceId(event.target.value)}
              placeholder="my-project"
              autoFocus
            />
          </label>
          <label className="block space-y-1 text-[11px] text-muted-foreground">
            <span>Repository path</span>
            <input
              aria-label="Repository path"
              className={fieldClass}
              value={repoPath}
              onChange={(event) => setRepoPath(event.target.value)}
              placeholder="/path/to/repository"
            />
          </label>
          {error ? <p className="text-[11px] text-destructive">{error}</p> : null}
        </div>
        <div className="flex justify-end gap-2 border-t border-border px-3 py-2">
          <button type="button" className="h-7 rounded-md px-2.5 text-xs text-muted-foreground hover:bg-accent" onClick={() => onCloseRef.current()}>
            Cancel
          </button>
          <button
            type="submit"
            disabled={submitting || !workspaceId.trim() || !repoPath.trim()}
            className="h-7 rounded-md bg-primary px-3 text-xs font-medium text-primary-foreground disabled:opacity-45"
          >
            Add Project
          </button>
        </div>
      </form>
    </div>
  );
}

type AddWorktreeDialogProps = {
  project: RegisteredProject;
  onClose: () => void;
  onCreated: (worktree: Worktree) => void | Promise<void>;
};

export function AddWorktreeDialog({ project, onClose, onCreated }: AddWorktreeDialogProps) {
  const [branches, setBranches] = useState<LocalBranch[]>([]);
  const [baseRef, setBaseRef] = useState("");
  const [slug, setSlug] = useState("");
  const [loadingBranches, setLoadingBranches] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let alive = true;
    setLoadingBranches(true);
    setError(null);
    void listProjectBranches(project.workspaceId)
      .then((items) => {
        if (!alive) return;
        setBranches(items);
        const preferred = items.find((branch) => branch.isCurrent) ?? items[0];
        setBaseRef(preferred?.name ?? "");
      })
      .catch((cause) => {
        if (!alive) return;
        setError(cause instanceof Error ? cause.message : "Could not load local branches.");
      })
      .finally(() => {
        if (alive) setLoadingBranches(false);
      });
    return () => {
      alive = false;
    };
  }, [project.workspaceId]);

  const submit = async (event: FormEvent) => {
    event.preventDefault();
    const trimmedSlug = slug.trim();
    if (!trimmedSlug || !baseRef || submitting) return;
    setSubmitting(true);
    setError(null);
    try {
      const worktree = await createWorktree({
        workspaceId: project.workspaceId,
        worktree: { wsId: project.workspaceId, slug: trimmedSlug },
        baseRef,
      });
      await onCreated(worktree);
      onClose();
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : "Could not create the worktree.");
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 z-40 flex items-center justify-center bg-black/45 p-6" role="presentation">
      <form
        aria-label="Add Worktree"
        className="w-full max-w-[420px] overflow-hidden rounded-lg border border-border bg-card shadow-2xl"
        onSubmit={submit}
      >
        <div className="flex h-9 items-center border-b border-border px-3">
          <GitBranch className="mr-2 size-3.5 text-muted-foreground" />
          <h2 className="min-w-0 flex-1 truncate text-[13px] font-medium">Add Worktree · {project.workspaceId}</h2>
          <button
            type="button"
            aria-label="Close Add Worktree"
            className="rounded p-1 text-muted-foreground hover:bg-accent hover:text-foreground"
            onClick={onClose}
          >
            <X className="size-3.5" />
          </button>
        </div>
        <div className="space-y-3 p-3">
          <label className="block space-y-1 text-[11px] text-muted-foreground">
            <span>Worktree slug</span>
            <input
              aria-label="Worktree slug"
              className={fieldClass}
              value={slug}
              onChange={(event) => setSlug(event.target.value)}
              placeholder="feature-ui"
              autoFocus
            />
          </label>
          <label className="block space-y-1 text-[11px] text-muted-foreground">
            <span>Base branch</span>
            <select
              aria-label="Base branch"
              className={fieldClass}
              value={baseRef}
              disabled={loadingBranches || branches.length === 0}
              onChange={(event) => setBaseRef(event.target.value)}
            >
              {branches.map((branch) => (
                <option key={branch.name} value={branch.name}>
                  {branch.name}{branch.isCurrent ? " (current)" : ""}
                </option>
              ))}
            </select>
          </label>
          <p className="truncate text-[10px] text-muted-foreground/70">{project.repoRoot}</p>
          {error ? <p className="text-[11px] text-destructive">{error}</p> : null}
        </div>
        <div className="flex justify-end gap-2 border-t border-border px-3 py-2">
          <button type="button" className="h-7 rounded-md px-2.5 text-xs text-muted-foreground hover:bg-accent" onClick={onClose}>
            Cancel
          </button>
          <button
            type="submit"
            disabled={submitting || loadingBranches || !slug.trim() || !baseRef}
            className="h-7 rounded-md bg-primary px-3 text-xs font-medium text-primary-foreground disabled:opacity-45"
          >
            Create Worktree
          </button>
        </div>
      </form>
    </div>
  );
}

import { useSortable } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import { Globe, Pin, TerminalSquare, X } from "lucide-react";
import { memo, useMemo, type KeyboardEvent, type MouseEvent, type PointerEvent } from "react";

import { resolveActivityIndicator, type ActivitySummary } from "../../lib/activity";
import { cn } from "../../lib/cn";
import type { WorkspaceTab } from "../../lib/types";
import { StatusDot } from "../ui/StatusDot";

type SortableTabProps = {
  tab: WorkspaceTab;
  groupId: string;
  index: number;
  active: boolean;
  unread: boolean;
  activity?: ActivitySummary;
  isRenaming: boolean;
  renameValue: string;
  onRenameValueChange: (value: string) => void;
  onCommitRename: (tabId: string) => void;
  onCancelRename: () => void;
  onActivate: (tabId: string) => void;
  onClose: (tabId: string) => void;
  onContextMenu: (event: MouseEvent, tab: WorkspaceTab) => void;
};

export const SortableTab = memo(function SortableTab({
  tab,
  groupId,
  index,
  active,
  unread,
  activity,
  isRenaming,
  renameValue,
  onRenameValueChange,
  onCommitRename,
  onCancelRename,
  onActivate,
  onClose,
  onContextMenu,
}: SortableTabProps) {
  const sortableData = useMemo(
    () => ({ type: "tab", tabId: tab.id, groupId, index }),
    [tab.id, groupId, index],
  );
  const sortable = useSortable({
    id: `tab:${tab.id}`,
    disabled: isRenaming,
    data: sortableData,
  });
  const resolvedActivity = tab.kind === "browser" ? null : resolveActivityIndicator(activity);
  const activityIndicator = unread && (resolvedActivity === null || resolvedActivity === "done") ? "unread" : resolvedActivity;
  const isPinned = Boolean(tab.pinned);

  const style = {
    transform: CSS.Transform.toString(sortable.transform),
    transition: sortable.transition,
  };

  const stopPointer = (event: PointerEvent) => event.stopPropagation();

  return (
    <div
      ref={sortable.setNodeRef}
      {...sortable.attributes}
      {...sortable.listeners}
      role="tab"
      aria-selected={active}
      tabIndex={active ? 0 : -1}
      data-tab-dnd-id={tab.id}
      data-tab-group-id={groupId}
      data-tab-index={index}
      data-dnd-type="tab"
      draggable={false}
      onContextMenu={(event) => onContextMenu(event, tab)}
      onClick={() => onActivate(tab.id)}
      onKeyDown={(event: KeyboardEvent) => {
        if (event.key === "Enter" || event.key === " ") {
          event.preventDefault();
          onActivate(tab.id);
        }
      }}
      style={style}
      className={cn(
        "no-drag group relative flex min-w-tab max-w-tab cursor-pointer touch-none items-center gap-1.5 border-r border-border px-2 text-[12px] transition-colors outline-none focus-visible:ring-1 focus-visible:ring-inset focus-visible:ring-ring",
        active ? "bg-accent text-foreground" : "bg-card text-muted-foreground hover:bg-accent/45 hover:text-foreground",
        sortable.isDragging && "z-40 opacity-30",
      )}
    >
      {tab.kind === "browser" ? (
        <Globe className="size-3 shrink-0 text-primary" />
      ) : activityIndicator ? (
        <span
          data-testid={activityIndicator === "unread" ? "tab-unread-dot" : `tab-${activityIndicator}-indicator`}
          aria-label={`Agent ${activityIndicator}`}
          className="inline-flex size-3 shrink-0 items-center justify-center"
        >
          <StatusDot state={activityIndicator} />
        </span>
      ) : (
        <TerminalSquare className="size-3 shrink-0" />
      )}

      {isRenaming ? (
        <input
          type="text"
          value={renameValue}
          autoFocus
          data-tab-rename-input="true"
          onClick={(event) => event.stopPropagation()}
          onPointerDown={stopPointer}
          onChange={(event) => onRenameValueChange(event.target.value)}
          onBlur={() => onCommitRename(tab.id)}
          onKeyDown={(event) => {
            event.stopPropagation();
            if (event.key === "Enter") {
              event.preventDefault();
              event.currentTarget.blur();
            } else if (event.key === "Escape") {
              event.preventDefault();
              onCancelRename();
              event.currentTarget.blur();
            }
          }}
          className="min-w-0 flex-1 rounded border border-ring bg-background px-1 py-0.5 text-xs text-foreground outline-none"
        />
      ) : (
        <span className="min-w-0 flex-1 truncate text-left">{tab.label}</span>
      )}

      {isPinned ? <Pin className="size-2.5 shrink-0 text-muted-foreground/80" aria-label="Pinned tab" /> : null}

      {!isPinned ? (
        <span
          role="button"
          tabIndex={0}
          aria-label={`Close ${tab.label}`}
