     4	import type { BrowserTab } from "../lib/types";
     5	
     6	interface BrowserToolbarProps {
     7	  tab: BrowserTab;
     8	  onNavigate: (url: string) => void;
     9	  onReload: () => void;
    10	  onGoBack?: () => void;
    11	  onGoForward?: () => void;
    12	}
    13	
    14	export function BrowserToolbar({
    15	  tab,
    16	  onNavigate,
    17	  onReload,
    18	  onGoBack,
    19	  onGoForward,
    20	}: BrowserToolbarProps) {
    21	  const [inputUrl, setInputUrl] = useState(tab.url);
    22	  const [zoomFactor, setZoomFactor] = useState(1.0);
    23	
    24	  useEffect(() => {
    25	    setInputUrl(tab.url);
    26	  }, [tab.url]);
    27	
    28	  const handleSubmit = (e: React.FormEvent) => {
    29	    e.preventDefault();
    30	    let url = inputUrl.trim();
    31	    if (!url) return;
    32	    if (!url.startsWith("http://") && !url.startsWith("https://") && url !== "about:blank") {
    33	      if (url.startsWith("localhost") || url.startsWith("127.0.0.1")) {
    34	        url = `http://${url}`;
    35	      } else {
    36	        url = `https://${url}`;
    37	      }
    38	    }
    39	    onNavigate(url);
    40	  };
    41	
    42	  const handleExternalOpen = () => {
    43	    if (tab.url && tab.url !== "about:blank") {
    44	      void openExternalUrl(tab.url);
    45	    }
    46	  };
    47	
    48	  const handleZoomIn = async () => {
    49	    const nextZoom = Math.min(2.0, Math.round((zoomFactor + 0.1) * 10) / 10);
    50	    setZoomFactor(nextZoom);
    51	    try {
    52	      await setBrowserZoom(tab.browserId, nextZoom);
    53	    } catch {
    54	      // ignore
    55	    }
    56	  };
    57	
    58	  const handleZoomOut = async () => {
    59	    const nextZoom = Math.max(0.5, Math.round((zoomFactor - 0.1) * 10) / 10);
    60	    setZoomFactor(nextZoom);
    61	    try {
    62	      await setBrowserZoom(tab.browserId, nextZoom);
    63	    } catch {
    64	      // ignore
    65	    }
    66	  };
    67	
    68	  const handleFocus = async () => {
    69	    try {
    70	      await focusBrowser(tab.browserId);
    71	    } catch {
    72	      // ignore
    73	    }
    74	  };
    75	
    76	  const handleSyncState = async () => {
    77	    try {
    78	      const state = await getBrowserState(tab.browserId);
    79	      if (state.url && state.url !== inputUrl) {
    80	        setInputUrl(state.url);
    81	      }
    82	    } catch {
    83	      // ignore
    84	    }
    85	  };
    86	
    87	  return (
    88	    <div className="flex items-center gap-2 px-3 py-1.5 bg-sidebar border-b border-border text-xs text-foreground select-none">
    89	      <div className="flex items-center gap-1">
    90	        <button
    91	          type="button"
    92	          disabled={!tab.canGoBack}
    93	          onClick={onGoBack}
    94	          aria-label="Back"
    95	          className="p-1 rounded hover:bg-muted disabled:opacity-30 transition-colors"
    96	        >
    97	          <ArrowLeft className="w-3.5 h-3.5" />
    98	        </button>
    99	        <button
   100	          type="button"
   101	          disabled={!tab.canGoForward}
   102	          onClick={onGoForward}
   103	          aria-label="Forward"
   104	          className="p-1 rounded hover:bg-muted disabled:opacity-30 transition-colors"
   105	        >
   106	          <ArrowRight className="w-3.5 h-3.5" />
   107	        </button>
   108	        <button
   109	          type="button"
   110	          onClick={onReload}
   111	          aria-label="Reload"
   112	          className="p-1 rounded hover:bg-muted transition-colors"
   113	        >
   114	          <RotateCw className={`w-3.5 h-3.5 ${tab.loading ? "animate-spin" : ""}`} />
   115	        </button>
   116	      </div>
   117	
   118	      <form onSubmit={handleSubmit} className="flex-1 flex items-center">
   119	        <input
   120	          type="text"
   121	          value={inputUrl}
   122	          onChange={(e) => setInputUrl(e.target.value)}
   123	          placeholder="Search or enter URL"
   124	          aria-label="URL address bar"
   125	          className="w-full bg-background border border-border rounded px-2.5 py-1 text-xs text-foreground focus:outline-none focus:border-primary font-mono"
   126	        />
   127	      </form>
   128	
   129	      <div className="flex items-center gap-0.5 border-l border-border/70 pl-1.5">
   130	        <button
   131	          type="button"
   132	          onClick={handleZoomOut}
   133	          title="Zoom out"
   134	          aria-label="Zoom out"
   135	          className="p-1 rounded hover:bg-muted text-muted-foreground hover:text-foreground transition-colors"
   136	        >
   137	          <ZoomOut className="w-3.5 h-3.5" />
   138	        </button>
   139	        <span className="font-mono text-[10px] text-muted-foreground w-8 text-center">
   140	          {Math.round(zoomFactor * 100)}%
   141	        </span>
   142	        <button
   143	          type="button"
   144	          onClick={handleZoomIn}
   145	          title="Zoom in"
   146	          aria-label="Zoom in"
   147	          className="p-1 rounded hover:bg-muted text-muted-foreground hover:text-foreground transition-colors"
   148	        >
   149	          <ZoomIn className="w-3.5 h-3.5" />
   150	        </button>
   151	      </div>
   152	
   153	      <div className="flex items-center gap-0.5 border-l border-border/70 pl-1.5">
   154	        <button
   155	          type="button"
   156	          onClick={handleFocus}
   157	          title="Focus webview"
   158	          aria-label="Focus webview"
   159	          className="p-1 rounded hover:bg-muted text-muted-foreground hover:text-foreground transition-colors"
   160	        >
   161	          <Target className="w-3.5 h-3.5" />
   162	        </button>
   163	        <button
   164	          type="button"
   165	          onClick={handleSyncState}
   166	          title="Sync browser state"
   167	          aria-label="Sync browser state"
   168	          className="p-1 rounded hover:bg-muted text-muted-foreground hover:text-foreground transition-colors"
   169	        >
   170	          <RefreshCw className="w-3.5 h-3.5" />
   171	        </button>
   172	        <button
   173	          type="button"
   174	          onClick={handleExternalOpen}
   175	          title="Open in default browser"
   176	          aria-label="Open in external browser"
   177	          className="p-1 rounded hover:bg-muted transition-colors"
   178	        >
   179	          <ExternalLink className="w-3.5 h-3.5 text-muted-foreground" />
   180	        </button>
   181	      </div>
   182	    </div>
   183	  );
   184	}

