     1	import { useRef, useEffect } from "react";
     2	import { setBrowserBounds, setBrowserVisible } from "../lib/browserTauri";
     3	import { BrowserToolbar } from "./BrowserToolbar";
     4	import type { BrowserTab } from "../lib/types";
     5	
     6	interface BrowserPaneProps {
     7	  tab: BrowserTab;
     8	  visible?: boolean;
     9	  onNavigate: (url: string) => void;
    10	  onReload: () => void;
    11	}
    12	
    13	export function BrowserPane({ tab, visible = true, onNavigate, onReload }: BrowserPaneProps) {
    14	  const containerRef = useRef<HTMLDivElement>(null);
    15	
    16	  useEffect(() => {
    17	    const el = containerRef.current;
    18	    if (!el) return;
    19	
    20	    const updateVisibility = (nextVisible: boolean) => {
    21	      void setBrowserVisible(tab.browserId, nextVisible).catch(() => undefined);
    22	    };
    23	
    24	    const updateBounds = () => {
    25	      if (!visible) {
    26	        updateVisibility(false);
    27	        return;
    28	      }
    29	
    30	      const rect = el.getBoundingClientRect();
    31	      void setBrowserBounds(tab.browserId, {
    32	        x: rect.x,
    33	        y: rect.y,
    34	        width: rect.width,
    35	        height: rect.height,
    36	      }).catch(() => undefined);
    37	      updateVisibility(true);
    38	    };
    39	
    40	    updateBounds();
    41	
    42	    const resizeObserver = new ResizeObserver(() => {
    43	      updateBounds();
    44	    });
    45	
    46	    resizeObserver.observe(el);
    47	    window.addEventListener("resize", updateBounds);
    48	
    49	    return () => {
    50	      resizeObserver.disconnect();
    51	      window.removeEventListener("resize", updateBounds);
    52	      // Native child webviews outlive React DOM nodes; cleanup also covers Fast Refresh remounts.
    53	      updateVisibility(false);
    54	    };
    55	  }, [tab.browserId, visible]);
    56	
    57	  return (
    58	    <div className="flex flex-col w-full h-full bg-background overflow-hidden">
    59	      <BrowserToolbar tab={tab} onNavigate={onNavigate} onReload={onReload} />
    60	      <div
    61	        ref={containerRef}
    62	        data-testid="browser-viewport"
    63	        className="flex-1 w-full bg-card relative"
    64	      />
    65	    </div>
    66	  );
    67	}
