262	export function edgeToSplit(edge: TabDropEdge): { direction: PaneDirection; position: "first" | "second" } {
263	  if (edge === "left") return { direction: "horizontal", position: "first" };
264	  if (edge === "right") return { direction: "horizontal", position: "second" };
